WITH lines AS (SELECT id, plan, effective_from, currency, EXPLODE_OUTER(tier_prices) AS tier_value FROM price_tiers) SELECT id, plan, effective_from, currency, tier_value, RANK() OVER (PARTITION BY plan ORDER BY tier_value NULLS FIRST) AS tier_value_rank, CUME_DIST() OVER (PARTITION BY plan ORDER BY tier_value DESC) AS tier_value_cume_dist, MIN(tier_value) OVER w_running AS plan_min_tier_value, DENSE_RANK() OVER (PARTITION BY currency ORDER BY tier_value NULLS LAST) AS tier_value_dense_rank, RANK() OVER (ORDER BY tier_value) AS tier_value_rank_2 FROM lines WINDOW w_running AS (PARTITION BY plan)
